import json
import os

PATH = os.environ.get("NOTES_FILE", "notes.json")


def load():
    if not os.path.exists(PATH):
        return []
    with open(PATH, encoding="utf-8") as f:
        return json.load(f)


def add(text):
    notes = load() + [text]
    with open(PATH, "w", encoding="utf-8") as f:
        json.dump(notes, f)
